vidual component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"}},\"required\":[\"name\",\"id\",\"available\"],\"title\":\"HourlyMatching\",\"type\":\"object\"},\"HydroGenerationCost\":{\"description\":\"Cost representation for hydro gen units\",\"properties\":{\"cost_type\":{\"const\":\"HYDRO_GEN\",\"default\":\"HYDRO_GEN\",\"type\":\"string\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-4643c51d11717913e8d0.json#/components/schemas/ProductionVariableCostCurve\"}},\"required\":[\"variable_operation_cost\"],\"title\":\"HydroGenerationCost\",\"type\":\"object\"},\"IncrementalCurve\":{\"description\":\"A curve whose y values are the marginal rate `f'(x)` at production level `x` — the native form for market bid stacks and incremental heat rate data. `initial_input` records the total input at the minimum production point, anchoring the absolute level and enabling conversion to an `InputOutputCurve`. Use `InputOutputCurve` when the data gives total cost at each output level.\",\"properties\":{\"curve_type\":{\"const\":\"INCREMENTAL\",\"default\":\"INCREMENTAL\",\"type\":\"string\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"#/components/schemas/LinearFunctionData\",\"PIECEWISE_STEP\":\"#/components/schemas/PiecewiseStepData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-4643c51d11717913e8d0.json#/components/schemas/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/root-4643c51d11717913e8d0.json#/components/schemas/PiecewiseStepData\"}]},\"initial_input\":{\"type\":\"number\"},\"input_at_zero\":{\"type\":\"number\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"IncrementalCurve\",\"type\":\"object\"},\"InputOutputCurve\":{\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"propo