ueCurve\",\"type\":\"object\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"},\"power_systems_type\":{\"description\":\"Corresponding type to be used in PCM modeling.\",\"type\":\"string\"},\"requirements\":{\"default\":[],\"description\":\"List of requirement IDs associated with the component.\",\"items\":{\"type\":\"integer\"},\"type\":\"array\"},\"start_node\":{\"description\":\"Start node for transport technology.\",\"type\":\"integer\"},\"unit_size\":{\"description\":\"Used for integer investment decisions. Represents the rating capacity of individual new lines. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"}},\"required\":[\"available\",\"end_node\",\"financial_data\",\"id\",\"name\",\"power_systems_type\",\"start_node\"],\"title\":\"NodalHVDCTransportTechnology\",\"type\":\"object\"},\"Node\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A unit of spatial aggregation for nodal capacity expansion models. Used to define locations for supply, demand, transport, and storage technologies and the relevant policy requirements.\",\"properties\":{\"bus_type\":{\"default\":\"PQ\",\"description\":\"AC Bus Type for a node.\",\"enum\":[\"PQ\",\"PV\",\"REF\",\"ISOLATED\",\"SLACK\"],\"title\":\"ACBusType\",\"type\":\"string\"},\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"}},\"required\":[\"id\",\"name\"],\"title\":\"Node\",\"type\":\"object\"},\"PiecewiseLinearData\":{\"description\":\"Data for a piecewise linear function defined by (x, y) points and interpolated linearly between consecutive ones. The y values are absolute values at each x, not per-segment slopes; use `PiecewiseStepData` when the data gives per-segment rates. Points run in ascending x order, and two of them define one segment.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_LINEAR\",